describe('Save Card Details for Future Purchases', () => {
  beforeEach(() => {
    cy.visit('/checkout');
    cy.get('[data-testid="payment-section"]').should('be.visible');
  });

  it('should successfully save card details for future purchases', () => {
    // Navigate to payment method section
    cy.get('[data-testid="payment-method-tab"]').click();

    // Fill in card details
    cy.get('[data-testid="card-number-input"]').type('4532015112830366');
    cy.get('[data-testid="card-holder-input"]').type('John Doe');
    cy.get('[data-testid="expiry-month-select"]').select('12');
    cy.get('[data-testid="expiry-year-select"]').select('2026');
    cy.get('[data-testid="cvv-input"]').type('123');

    // Check the save card checkbox
    cy.get('[data-testid="save-card-checkbox"]').check();
    cy.get('[data-testid="save-card-checkbox"]').should('be.checked');

    // Complete purchase
    cy.get('[data-testid="complete-purchase-btn"]').click();

    // Verify success message
    cy.get('[data-testid="success-message"]').should('contain', 'Card saved successfully');
    cy.get('[data-testid="order-confirmation"]').should('be.visible');

    // Verify card appears in saved cards list
    cy.visit('/account/saved-cards');
    cy.get('[data-testid="saved-card-item"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="saved-card-item"]').first().should('contain', '4532');
  });

  it('should handle invalid card details and prevent saving', () => {
    // Navigate to payment method section
    cy.get('[data-testid="payment-method-tab"]').click();

    // Fill in invalid card details
    cy.get('[data-testid="card-number-input"]').type('1234567890123456');
    cy.get('[data-testid="card-holder-input"]').type('Jane Doe');
    cy.get('[data-testid="expiry-month-select"]').select('01');
    cy.get('[data-testid="expiry-year-select"]').select('2020');
    cy.get('[data-testid="cvv-input"]').type('12');

    // Check save card checkbox
    cy.get('[data-testid="save-card-checkbox"]').check();

    // Attempt to complete purchase
    cy.get('[data-testid="complete-purchase-btn"]').click();

    // Verify error messages appear
    cy.get('[data-testid="card-error-message"]').should('be.visible');
    cy.get('[data-testid="cvv-error-message"]').should('contain', 'CVV must be 3 or 4 digits');

    // Verify card was not saved
    cy.visit('/account/saved-cards');
    cy.get('[data-testid="saved-card-item"]').should('not.contain', '1234');
  });

  it('should allow user to skip saving card details', () => {
    // Navigate to payment method section
    cy.get('[data-testid="payment-method-tab"]').click();

    // Fill in valid card details
    cy.get('[data-testid="card-number-input"]').type('4532015112830366');
    cy.get('[data-testid="card-holder-input"]').type('John Doe');
    cy.get('[data-testid="expiry-month-select"]').select('12');
    cy.get('[data-testid="expiry-year-select"]').select('2026');
    cy.get('[data-testid="cvv-input"]').type('123');

    // Do NOT check the save card checkbox
    cy.get('[data-testid="save-card-checkbox"]').should('not.be.checked');

    // Complete purchase
    cy.get('[data-testid="complete-purchase-btn"]').click();

    // Verify success message
    cy.get('[data-testid="success-message"]').should('contain', 'Order placed successfully');

    // Verify card was not saved
    cy.visit('/account/saved-cards');
    cy.get('[data-testid="saved-card-item"]').should('not.contain', '4532');
  });

  it('should display saved card option on subsequent purchases', () => {
    // Assume card was previously saved
    cy.visit('/checkout');
    cy.get('[data-testid="payment-method-tab"]').click();

    // Verify saved cards section is visible
    cy.get('[data-testid="saved-cards-section"]').should('be.visible');
    cy.get('[data-testid="saved-card-option"]').should('have.length.greaterThan', 0);

    // Select a saved card
    cy.get('[data-testid="saved-card-option"]').first().click();
    cy.get('[data-testid="saved-card-option"]').first().should('have.class', 'selected');

    // Verify CVV input appears for saved card
    cy.get('[data-testid="cvv-input-for-saved-card"]').should('be.visible');
    cy.get('[data-testid="cvv-input-for-saved-card"]').type('123');

    // Complete purchase
    cy.get('[data-testid="complete-purchase-btn"]').click();

    // Verify success
    cy.get('[data-testid="success-message"]').should('contain', 'Order placed successfully');
  });
});
